export function reduceEvent(state,event){if(event.type==='STATE_SNAPSHOT')return structuredClone(event.snapshot);if(event.type==='STATE_DELTA'){const next=structuredClone(state);for(const p of event.delta){if(!['add','replace'].includes(p.op)||!/^\/[a-zA-Z]+$/.test(p.path))throw Error('Only top-level add/replace supported; use snapshot for other patches.');const k=p.path.slice(1);if(!Object.hasOwn(next,k))throw Error('Unknown state key: '+k);next[k]=structuredClone(p.value);}return next;}return state;}
